			expect(packet.slots[0]).toBe(128);
			expect(packet.sacn).toMatchObject({
				preambleSize: 0x10,
				rootVector: 0x00000004,
				framingVector: 0x00000002,
				propertyValueCount: 513,
				startCode: 0,
